async Task<Location> GetLocationAsync(CancellationToken ct)
{
    var tcs = new TaskCompletionSource<Location>(
        TaskCreationOptions.RunContinuationsAsynchronously);   // why — in a card below
    void OnFix(Location l)    => tcs.TrySetResult(l);
    void OnError(Exception e) => tcs.TrySetException(e);

    gps.OnFix += OnFix; gps.OnError += OnError;
    using var reg = ct.Register(() => tcs.TrySetCanceled(ct));
    try
    {
        gps.Start();
        return await tcs.Task;
    }
    finally { gps.OnFix -= OnFix; gps.OnError -= OnError; }
}

cards/5/code:
// success: OnFix → TrySetResult → await returned the Location → finally unsubscribed
// error:   OnError → TrySetException → await threw it → finally unsubscribed
// cancel:  Cancel → the Register callback → TrySetCanceled → await threw OperationCanceledException
//          → finally unsubscribed, using removed the registration
// a late OnFix after cancellation: the handler is gone; if it got in first, TrySetResult returns false

